import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // bound _value to avoid overflow in depositsCount and excessive gas
        vm.assume(_target != address(0));
