pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint public initialDepositsCount;

    function setUp() public { 
        c = new C(); 
        initialDepositsCount = c.depositsCount();
    }

    function testFuzz_property(address target, uint amount) public {
        vm.assume(target != address(0) && target != address(c));
        vm.assume(amount > 0 && amount <= address(this).balance);

        uint countBefore = c.depositsCount();

        // Fund this contract so we can send money
        vm.deal(address(this), amount);

        // Use prank to make the owner call sendMoney
        vm.prank(c.owner());
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("sendMoney(address,uint256)", target, amount));

        if (success) {
            assertTrue(c.depositsCount() == countBefore + 1, "depositsCount should increase by 1 after successful sendMoney");
        } else {
            assertTrue(c.depositsCount() == countBefore, "depositsCount should not change if sendMoney fails");
        }
    }
}

