pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint value, uint ethAmount) public {
        // Ensure enough ETH for the call
        vm.deal(address(c), ethAmount + 1 ether);
        vm.prank(c.owner());
        // Simulate a deposit that increments depositsCount
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "deposit failed");
        // Now call sendMoney with fuzzed parameters
        c.sendMoney(target, value);
        // Property: depositsCount should never overflow; after any sequence of deposits and sends,
        // it remains non-negative (since it only increments in reference) - but with decrement bug it could go negative
        // However, uint cannot go negative, so we check that depositsCount does not underflow from a previous increment.
        // The postcondition after sendMoney is called: depositsCount is unchanged because sendMoney does not affect depositsCount.
        // The bug only manifests in the receive function, so we ensure that after the deposit, depositsCount >= 1.
        assertTrue(c.depositsCount() >= 1);
    }
}

