pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value > 0); // to avoid zero-value calls that don't trigger receive()
        vm.assume(target != address(0)); // avoid revert from sendMoney to address(0)
        vm.assume(target != address(c)); // avoid reentrancy-like complications

        uint256 countBefore = c.depositsCount();

        // Fund this contract so it can send value
        vm.deal(address(this), value);
        // Impersonate owner to call sendMoney
        address owner = c.owner();
        vm.prank(owner);
        (bool success,) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // The sendMoney call executes a call to target, which may call receive()
        if (success) {
            uint256 countAfter = c.depositsCount();
            // Each receive() call increments depositsCount by 1
            // The sendMoney triggers one receive() on the target (if payable)
            // So count should increase by exactly 1
            assertTrue(countAfter == countBefore + 1, "depositsCount did not increase by exactly 1 after sendMoney");
        } else {
            // If sendMoney failed (e.g., target not payable), depositsCount unchanged
            uint256 countAfter = c.depositsCount();
            assertTrue(countAfter == countBefore, "depositsCount changed despite failed sendMoney");
        }
    }
}

