pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 depositAmount, uint256 sendAmount, address target) public {
        vm.assume(sender != address(0) && target != address(0));
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: depositAmount}("");
        vm.assume(ok);
        // Now call sendMoney — the bug means the contract balance changes differently
        vm.prank(c.owner());
        (bool revertOk,) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, sendAmount));
        // After sendMoney, the contract balance should be: depositsCount (in wei) - sendAmount (if not reverted)
        uint256 expectedBalance = c.depositsCount();
        if (!revertOk) {
            expectedBalance = expectedBalance - sendAmount;
        }
        assertTrue(address(c).balance == expectedBalance);
    }
}

