pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address sender, uint256 depositValue, uint256 sendValue, address target) public {
        // Restrict deposits to 1 wei to keep balance predictable
        vm.assume(depositValue == 1);
        // Restrict sendValue to be <= 1 ether to avoid overflows
        sendValue = bound(sendValue, 1, 1 ether);
        // Ensure target is not the contract itself to avoid self-call issues
        vm.assume(target != address(c));

        // Simulate deposits: call receive with depositValue
        vm.deal(sender, depositValue);
        vm.prank(sender);
        (bool successDeposit, ) = address(c).call{value: depositValue}("");
        require(successDeposit, "deposit failed");

        // Record state before sendMoney
        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        // Call sendMoney as owner
        vm.prank(c.owner());
        c.sendMoney(target, sendValue);

        // After sendMoney, the contract's balance should be: depositsBefore (since each deposit is 1 wei) - sendValue (if send succeeded, else unchanged)
        uint256 expectedBalance = depositsBefore - sendValue;
        assertTrue(address(c).balance == expectedBalance, "Balance after sendMoney does not match deposits minus sent amount");
    }
}

